target.css:
:root {
  --ink: #1e2d3d;
  --muted: #687789;
  --panel: #ffffff;
  --navy: #203a57;
  --blue: #3876b7;
  --pale-blue: #eaf3fb;
  --line: #d8e2eb;
  --mint: #dff3e9;
  --green: #237a59;
  --amber: #f8ebc7;
  --orange: #ab6b12;
  --soft: #f7fafc;
}

.dispatch {
  box-sizing: border-box;
  width: 490px;
  padding: 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-top: 4px solid var(--navy);
  border-radius: 10px;
  color: var(--ink);
}

.topbar,
.route-panel,
.platform-head,
.platform-item,
.legend {
  display: flex;
  align-items: center;
}

.topbar {
  justify-content: space-between;
  margin-bottom: 8px;
}

.title-group {
  min-width: 0;
}

.eyebrow,
.route-meta,
.metric-label,
.metric-note {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.07em;
  line-height: 1.1;
  text-transform: uppercase;
}

h1 {
  margin: 3px 0 0;
  color: var(--navy);
  font-size: 18px;
  font-weight: 750;
  letter-spacing: -0.03em;
  line-height: 1;
}

.live {
  padding: 4px 7px;
  background: var(--mint);
  border-radius: 999px;
  color: var(--green);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.route-panel {
  gap: 10px;
  padding: 8px 9px;
  background: var(--navy);
  border-radius: 7px;
  color: var(--panel);
}

.route-copy {
  flex: 1;
}

.route-panel .route-meta {
  color: var(--pale-blue);
  opacity: 0.78;
}

.route-copy strong {
  display: block;
  margin-top: 3px;
  font-size: 13px;
  line-height: 1;
}

.eta {
  min-width: 53px;
  padding-left: 9px;
  border-left: 1px solid var(--blue);
}

.eta span {
  display: block;
  color: var(--pale-blue);
  font-size: 9px;
  line-height: 1;
}

.eta strong {
  display: block;
  margin-top: 3px;
  font-size: 13px;
  line-height: 1;
}

.signal-button {
  padding: 6px 8px;
  background: var(--amber);
  border: 0;
  border-radius: 4px;
  color: var(--orange);
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.status-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin: 8px 0;
}

.metric {
  min-width: 0;
  padding: 7px 8px;
  background: var(--soft);
  border: 1px solid var(--line);
  border-radius: 6px;
}

.metric strong {
  display: block;
  margin: 3px 0 2px;
  color: var(--navy);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1;
}

.metric-note {
  font-size: 8px;
  letter-spacing: 0;
  text-transform: none;
}

.clear {
  border-bottom: 3px solid var(--green);
}

.caution {
  border-bottom: 3px solid var(--orange);
}

.timing {
  border-bottom: 3px solid var(--blue);
}

.platforms {
  border: 1px solid var(--line);
  border-radius: 6px;
  overflow: hidden;
}

.platform-head {
  justify-content: space-between;
  padding: 6px 8px;
  background: var(--pale-blue);
  color: var(--navy);
  font-size: 10px;
  line-height: 1;
}

.platform-head span {
  color: var(--muted);
  font-size: 9px;
}

.platform-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.platform-item {
  gap: 7px;
  padding: 5px 8px;
  border-top: 1px solid var(--line);
  font-size: 11px;
  line-height: 1;
}

.platform-item strong {
  flex: 1;
  font-weight: 700;
}

.zone {
  display: inline-grid;
  width: 17px;
  height: 17px;
  place-items: center;
  background: var(--mint);
  border-radius: 4px;
  color: var(--green);
  font-size: 9px;
  font-weight: 800;
}

.zone.wait {
  background: var(--amber);
  color: var(--orange);
}

.arrival {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.legend {
  gap: 9px;
  margin-top: 7px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.dot.active {
  background: var(--green);
}

.dot.wait {
  background: var(--orange);
}

.updated {
  margin-left: auto;
  font-size: 8px;
}

